#include "engine.h"
#include <string.h>
static void put32(uint8_t *p,uint32_t v){for(int i=0;i<4;i++)p[i]=(uint8_t)(v>>(8*i));}
static uint32_t get32(const uint8_t *p){return (uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);}
static uint32_t checksum(const uint8_t *p,size_t n){uint32_t h=2166136261u;for(size_t i=0;i<n;i++){h^=p[i];h*=16777619u;}return h;}
void et_init(EtGame *g,uint32_t seed){memset(g,0,sizeof(*g));g->state=ET_TITLE;g->rng=seed?seed:0x9e3779b9u;g->entities[0]=(EtEntity){.x=10,.y=7,.active=1,.solid=1,.kind=1};for(int y=0;y<ET_MAP_H;y++)for(int x=0;x<ET_MAP_W;x++)if(x==0||y==0||x==ET_MAP_W-1||y==ET_MAP_H-1)g->map.tiles[y][x]=1;}
uint32_t et_random(EtGame *g){uint32_t x=g->rng;x^=x<<13;x^=x>>17;x^=x<<5;return g->rng=x;}
int et_move(EtGame *g,unsigned entity,int dx,int dy){if(entity>=ET_MAX_ENTITIES||!g->entities[entity].active||dx<-1||dx>1||dy<-1||dy>1||(dx&&dy))return 0;int x=g->entities[entity].x+dx,y=g->entities[entity].y+dy;if(x<0||y<0||x>=ET_MAP_W||y>=ET_MAP_H||g->map.tiles[y][x])return 0;for(unsigned i=0;i<ET_MAX_ENTITIES;i++)if(i!=entity&&g->entities[i].active&&g->entities[i].solid&&g->entities[i].x==x&&g->entities[i].y==y)return 0;g->entities[entity].x=x;g->entities[entity].y=y;return 1;}
void et_step(EtGame *g,EtInput input){g->tick++;switch(g->state){case ET_TITLE:if(input==ET_CONFIRM)g->state=ET_WORLD;break;case ET_WORLD:if(input==ET_UP)et_move(g,0,0,-1);else if(input==ET_DOWN)et_move(g,0,0,1);else if(input==ET_LEFT)et_move(g,0,-1,0);else if(input==ET_RIGHT)et_move(g,0,1,0);else if(input==ET_CANCEL)g->state=ET_MENU;break;case ET_MENU:if(input==ET_CANCEL)g->state=ET_WORLD;break;case ET_BATTLE:if(input==ET_CANCEL)g->state=ET_WORLD;break;default:g->state=ET_TITLE;}}
uint16_t et_damage(uint16_t power,uint16_t attack,uint16_t defense,uint16_t level,uint16_t multiplier_percent){if(!power||!multiplier_percent)return 0;if(!defense)defense=1;uint64_t base=((uint64_t)(2u*level/5u+2u)*power*attack)/defense;base=base/50u+2u;uint64_t damage=base*multiplier_percent/100u;if(damage==0)damage=1;if(damage>UINT16_MAX)damage=UINT16_MAX;return (uint16_t)damage;}
int et_battle_attack(EtGame *g,EtSpirit *a,EtSpirit *d,uint16_t power,uint16_t multiplier_percent){if(!a||!d||!a->hp||!d->hp)return 0;uint16_t damage=et_damage(power,a->attack,d->defense,a->level,multiplier_percent);if(damage>d->hp)damage=d->hp;d->hp-=damage;g->battle_turn++;return damage;}
int et_save(const EtGame *g,uint8_t out[ET_SAVE_SIZE]){if(!g||!out)return 0;memset(out,0,ET_SAVE_SIZE);memcpy(out,"ETSV",4);out[4]=1;out[5]=(uint8_t)g->state;out[6]=(uint8_t)g->entities[0].x;out[7]=(uint8_t)g->entities[0].y;put32(out+8,g->tick);put32(out+12,g->rng);out[16]=g->party_count;put32(out+60,checksum(out,60));return 1;}
int et_load(EtGame *g,const uint8_t in[ET_SAVE_SIZE]){if(!g||!in||memcmp(in,"ETSV",4)||in[4]!=1||get32(in+60)!=checksum(in,60)||in[5]>ET_MENU||in[6]>=ET_MAP_W||in[7]>=ET_MAP_H||in[16]>ET_MAX_PARTY)return 0;EtGame temp;et_init(&temp,get32(in+12));temp.state=(EtState)in[5];temp.entities[0].x=in[6];temp.entities[0].y=in[7];if(temp.map.tiles[in[7]][in[6]])return 0;temp.tick=get32(in+8);temp.rng=get32(in+12);temp.party_count=in[16];*g=temp;return 1;}
